D = {
"Composto investigacional não aprovado; estágio clínico pode mudar com o desenvolvimento.": ("Investigational compound, not approved; clinical stage may change as development progresses.", "Compuesto en investigación no aprobado; la etapa clínica puede cambiar con el desarrollo."),
"Aprovado pela FDA e em outras jurisdições para acromegalia quando cirurgia ou outros tratamentos não controlam adequadamente a doença.": ("Approved by the FDA and in other jurisdictions for acromegaly when surgery or other treatments do not adequately control the disease.", "Aprobado por la FDA y en otras jurisdicciones para la acromegalia cuando la cirugía u otros tratamientos no controlan adecuadamente la enfermedad."),
"Investigacional e não aprovada; estudada em ensaios avançados para síndrome do intestino curto com falência intestinal.": ("Investigational and not approved; studied in late-stage trials for short bowel syndrome with intestinal failure.", "En investigación y no aprobada; estudiada en ensayos avanzados para el síndrome de intestino corto con insuficiencia intestinal."),
"Investigacional e não aprovada; em desenvolvimento para esteato-hepatite associada à disfunção metabólica e outras doenças hepáticas.": ("Investigational and not approved; in development for metabolic dysfunction-associated steatohepatitis and other liver diseases.", "En investigación y no aprobada; en desarrollo para la esteatohepatitis asociada a disfunción metabólica y otras enfermedades hepáticas."),
"Investigacional e não aprovada; estudos avançados avaliam doença hepática metabólica e hipertrigliceridemia.": ("Investigational and not approved; late-stage studies are evaluating metabolic liver disease and hypertriglyceridemia.", "En investigación y no aprobada; estudios avanzados evalúan enfermedad hepática metabólica e hipertrigliceridemia."),
"Aprovada pela FDA para constipação idiopática crônica e síndrome do intestino irritável com constipação em adultos; registro varia por país.": ("FDA-approved for chronic idiopathic constipation and irritable bowel syndrome with constipation in adults; registration varies by country.", "Aprobada por la FDA para el estreñimiento idiopático crónico y el síndrome del intestino irritable con estreñimiento en adultos; el registro varía según el país."),
"Secretina sintética aprovada nos Estados Unidos como agente diagnóstico em exames selecionados; não é aprovada para tratar doenças digestivas ou autismo.": ("Synthetic secretin approved in the United States as a diagnostic agent in selected tests; it is not approved to treat digestive diseases or autism.", "Secretina sintética aprobada en los Estados Unidos como agente diagnóstico en exámenes seleccionados; no está aprobada para tratar enfermedades digestivas ni autismo."),
"Aprovada em alguns países como agente diagnóstico para vesícula biliar e função pancreática; indicação depende da bula local.": ("Approved in some countries as a diagnostic agent for the gallbladder and pancreatic function; indication depends on the local label.", "Aprobada en algunos países como agente diagnóstico para la vesícula biliar y la función pancreática; la indicación depende del prospecto local."),
"Hormônio intestinal natural estudado em humanos; não aprovado como medicamento independente para uso terapêutico geral.": ("Natural gut hormone studied in humans; not approved as a stand-alone medicine for general therapeutic use.", "Hormona intestinal natural estudiada en humanos; no aprobada como medicamento independiente para uso terapéutico general."),
"Hormônio intestinal investigado como candidato terapêutico; não aprovado para obesidade ou diabetes.": ("Gut hormone investigated as a therapeutic candidate; not approved for obesity or diabetes.", "Hormona intestinal investigada como candidata terapéutica; no aprobada para obesidad ni diabetes."),
"Fragmento hormonal investigacional, sem aprovação como tratamento para obesidade ou distúrbios alimentares.": ("Investigational hormone fragment, not approved as a treatment for obesity or eating disorders.", "Fragmento hormonal en investigación, sin aprobación como tratamiento para la obesidad o los trastornos alimentarios."),
"Hormônio natural; formulações ou análogos foram investigados, mas a grelina não é aprovada como tratamento geral.": ("Natural hormone; formulations or analogues have been investigated, but ghrelin is not approved as a general treatment.", "Hormona natural; se han investigado formulaciones o análogos, pero la grelina no está aprobada como tratamiento general."),
"Aprovada em diversos países para diabetes; idade e indicações dependem da formulação e bula local.": ("Approved in several countries for diabetes; age and indications depend on the formulation and local label.", "Aprobada en diversos países para la diabetes; la edad y las indicaciones dependen de la formulación y del prospecto local."),
"Aprovada em diversos países para diabetes; formulação e faixa etária autorizada variam por produto.": ("Approved in several countries for diabetes; formulation and authorized age range vary by product.", "Aprobada en diversos países para la diabetes; la formulación y el rango de edad autorizado varían según el producto."),
"Aprovada em diversos países para diabetes; apresentações e indicações dependem da bula de cada produto.": ("Approved in several countries for diabetes; presentations and indications depend on each product's label.", "Aprobada en diversos países para la diabetes; las presentaciones e indicaciones dependen del prospecto de cada producto."),
"Aprovada em diversos países para diabetes; faixa etária e indicações variam conforme a bula local.": ("Approved in several countries for diabetes; age range and indications vary according to the local label.", "Aprobada en diversos países para la diabetes; el rango de edad y las indicaciones varían según el prospecto local."),
"Aprovada em algumas jurisdições, incluindo União Europeia, para diabetes em adultos; não presumir registro ou disponibilidade em outros países.": ("Approved in some jurisdictions, including the European Union, for diabetes in adults; do not assume registration or availability in other countries.", "Aprobada en algunas jurisdicciones, incluida la Unión Europea, para la diabetes en adultos; no se debe presumir registro o disponibilidad en otros países."),
"Aprovada pela FDA como teste oral para diagnosticar deficiência de GH em adultos; não e tratamento de reposicao de GH. Disponibilidade e registro variam por país.": ("FDA-approved as an oral test to diagnose adult GH deficiency; it is not a GH replacement treatment. Availability and registration vary by country.", "Aprobada por la FDA como prueba oral para diagnosticar la deficiencia de GH en adultos; no es un tratamiento de reposición de GH. La disponibilidad y el registro varían según el país."),
"Estudos clínicos sustentam seu desempenho diagnóstico na população adulta indicada. Os resultados não validam uso repetido para elevar GH.": ("Clinical studies support its diagnostic performance in the indicated adult population. The results do not validate repeated use to raise GH.", "Los estudios clínicos respaldan su desempeño diagnóstico en la población adulta indicada. Los resultados no validan el uso repetido para elevar la GH."),
"Agonista oral do receptor de grelina que favorece apetite e secrecao de GH; tambem pode elevar IGF-1.": ("Oral ghrelin receptor agonist that promotes appetite and GH secretion; it may also raise IGF-1.", "Agonista oral del receptor de grelina que favorece el apetito y la secreción de GH; también puede elevar el IGF-1."),
"Diabetes, alterações hepáticas, edema e câncer ativo exigem acompanhamento da equipe oncológica. Não é um produto de emagrecimento ou de musculação.": ("Diabetes, liver abnormalities, edema and active cancer require follow-up by the oncology team. It is not a weight-loss or bodybuilding product.", "La diabetes, las alteraciones hepáticas, el edema y el cáncer activo requieren seguimiento del equipo oncológico. No es un producto para adelgazar ni para musculación."),
"Baixa a moderada para pessoas; estudos humanos foram exploratorios e não estabeleceram uma indicação terapêutica aprovada.": ("Low to moderate in humans; human studies were exploratory and did not establish an approved therapeutic indication.", "Baja a moderada en personas; los estudios en humanos fueron exploratorios y no establecieron una indicación terapéutica aprobada."),
"Ativa o receptor GHS-R1a.": ("Activates the GHS-R1a receptor.", "Activa el receptor GHS-R1a."),
"Segurança prolongada e interações não estao estabelecidas; a estimulação de GH pode afetar glicemia e retenção de líquidos. Produtos sem controle podem conter contaminantes.": ("Long-term safety and interactions have not been established; GH stimulation may affect blood glucose and fluid retention. Unregulated products may contain contaminants.", "La seguridad a largo plazo y las interacciones no están establecidas; la estimulación de GH puede afectar la glucemia y la retención de líquidos. Los productos sin control pueden contener contaminantes."),
"Pode provocar liberação de GH e alterar apetite.": ("May trigger GH release and alter appetite.", "Puede provocar liberación de GH y alterar el apetito."),
"é uma molecula oral experimental, não um peptideo, que estimula GH por meio do receptor de grelina.": ("is an experimental oral molecule, not a peptide, that stimulates GH through the ghrelin receptor.", "es una molécula oral experimental, no un péptido, que estimula la GH a través del receptor de grelina."),
"A ação biológica pode persistir alem da presenca plasmática; não ha bula de medicamento aprovado para consulta.": ("Biological action may persist beyond plasma presence; there is no approved drug label to consult.", "La acción biológica puede persistir más allá de la presencia plasmática; no hay prospecto de medicamento aprobado para consultar."),
"HGH Frag designa um segmento curto da molecula de GH. A atividade atribuida em anuncios não equivale a efeito clínico demonstrado.": ("HGH Frag refers to a short segment of the GH molecule. The activity claimed in advertisements does not amount to a demonstrated clinical effect.", "HGH Frag designa un segmento corto de la molécula de GH. La actividad atribuida en anuncios no equivale a un efecto clínico demostrado."),
"Não ha recomendacao de armazenamento para uso humano.": ("There is no storage recommendation for human use.", "No hay recomendación de almacenamiento para uso humano."),
"A variante foi estudada em pesquisas de crescimento e sinalizacao celular, sem desenvolvimento terapêutico aprovado.": ("The variant has been studied in growth and cell signaling research, without approved therapeutic development.", "La variante se ha estudiado en investigaciones sobre crecimiento y señalización celular, sin desarrollo terapéutico aprobado."),
"Aprovada em alguns países, incluindo EUA e União Europeia, para falha de crescimento em crianças com deficiência primaria grave de IGF-1 ou indicações restritas da bula; não é aprovada para musculação ou envelhecimento.": ("Approved in some countries, including the US and the European Union, for growth failure in children with severe primary IGF-1 deficiency or restricted label indications; it is not approved for bodybuilding or aging.", "Aprobada en algunos países, incluidos EE. UU. y la Unión Europea, para la falla de crecimiento en niños con deficiencia primaria grave de IGF-1 o indicaciones restringidas del prospecto; no está aprobada para musculación ni envejecimiento."),
"Estudos clínicos e experiência pós-comercialização sustentam uso na indicação aprovada. Hipoglicemia é um risco importante, sobretudo em relacao a refeicoes.": ("Clinical studies and post-marketing experience support use in the approved indication. Hypoglycemia is an important risk, especially in relation to meals.", "Los estudios clínicos y la experiencia poscomercialización respaldan el uso en la indicación aprobada. La hipoglucemia es un riesgo importante, sobre todo en relación con las comidas."),
"Estrogênio fraco que se liga aos receptores de estrogênio (ERα e ERβ) e pode ser convertido em estradiol. Após a menopausa, é o principal estrogênio circulante, formado pela aromatização de androgênios no tecido adiposo.": ("A weak estrogen that binds to estrogen receptors (ERα and ERβ) and can be converted to estradiol. After menopause, it is the main circulating estrogen, formed by aromatization of androgens in adipose tissue.", "Estrógeno débil que se une a los receptores de estrógeno (ERα y ERβ) y puede convertirse en estradiol. Después de la menopausia, es el principal estrógeno circulante, formado por la aromatización de andrógenos en el tejido adiposo."),
"Pessoas com câncer hormônio-dependente, histórico de trombose, sangramento vaginal sem diagnóstico ou doença hepática grave.": ("People with hormone-dependent cancer, a history of thrombosis, undiagnosed vaginal bleeding or severe liver disease.", "Personas con cáncer hormonodependiente, antecedentes de trombosis, sangrado vaginal sin diagnóstico o enfermedad hepática grave."),
"Estrogênio de menor potência que se liga aos receptores de estrogênio, com ação mais localizada no trato urogenital em uso tópico vaginal. É o principal estrogênio da gestação, produzido pela placenta.": ("A lower-potency estrogen that binds to estrogen receptors, with a more localized action on the urogenital tract when used topically in the vagina. It is the main estrogen of pregnancy, produced by the placenta.", "Estrógeno de menor potencia que se une a los receptores de estrógeno, con acción más localizada en el tracto urogenital en uso tópico vaginal. Es el principal estrógeno del embarazo, producido por la placenta."),
"Pessoas com câncer de mama ou endométrio, trombose prévia, sangramento sem diagnóstico ou gravidez (como medicamento).": ("People with breast or endometrial cancer, prior thrombosis, undiagnosed bleeding or pregnancy (as a medicine).", "Personas con cáncer de mama o de endometrio, trombosis previa, sangrado sin diagnóstico o embarazo (como medicamento)."),
"Baixa: ensaios pequenos em esquizofrenia, depressão e dor mostraram resultados inconsistentes.": ("Low: small trials in schizophrenia, depression and pain showed inconsistent results.", "Baja: ensayos pequeños en esquizofrenia, depresión y dolor mostraron resultados inconsistentes."),
"É convertida enzimaticamente em outros esteroides.": ("It is enzymatically converted into other steroids.", "Se convierte enzimáticamente en otros esteroides."),
"Pode elevar estradiol, reduzir HDL, causar acne, ginecomastia e supressão do eixo gonadal; em mulheres, virilização. Proibida no esporte.": ("May raise estradiol, lower HDL, and cause acne, gynecomastia and suppression of the gonadal axis; virilization in women. Banned in sport.", "Puede elevar el estradiol, reducir el HDL, causar acné, ginecomastia y supresión del eje gonadal; en mujeres, virilización. Prohibida en el deporte."),
"Também é aromatizada em estrona.": ("It is also aromatized to estrone.", "También se aromatiza a estrona."),
"Em excesso associa-se a acne, queda de cabelo androgenética e crescimento prostático; riscos de androgênios incluem policitemia e alterações lipídicas. Proibida no esporte.": ("In excess it is associated with acne, androgenetic hair loss and prostate growth; androgen risks include polycythemia and lipid changes. Banned in sport.", "En exceso se asocia a acné, caída del cabello androgenética y crecimiento prostático; los riesgos de los andrógenos incluyen policitemia y alteraciones lipídicas. Prohibida en el deporte."),
"A DHT liga-se ao receptor de androgênios com alta afinidade.": ("DHT binds to the androgen receptor with high affinity.", "La DHT se une al receptor de andrógenos con alta afinidad."),
"Supressão do eixo gonadal, infertilidade, acne, alterações lipídicas, hipertensão, risco cardiovascular, lesão hepática (menos que orais), virilização em mulheres, atrofia testicular; contaminação em produtos ilícitos; doping.": ("Gonadal axis suppression, infertility, acne, lipid changes, hypertension, cardiovascular risk, liver injury (less than oral agents), virilization in women, testicular atrophy; contamination in illicit products; doping.", "Supresión del eje gonadal, infertilidad, acné, alteraciones lipídicas, hipertensión, riesgo cardiovascular, lesión hepática (menor que con los orales), virilización en mujeres, atrofia testicular; contaminación en productos ilícitos; dopaje."),
"Aumenta a síntese de proteínas e a produção de glóbulos vermelhos.": ("Increases protein synthesis and red blood cell production.", "Aumenta la síntesis de proteínas y la producción de glóbulos rojos."),
"Hepatotoxicidade (incluindo peliose hepática e tumores), colesterol HDL reduzido, supressão gonadal, virilização em mulheres e crianças, fechamento precoce das epífises; proibida no esporte.": ("Hepatotoxicity (including peliosis hepatis and tumors), reduced HDL cholesterol, gonadal suppression, virilization in women and children, premature epiphyseal closure; banned in sport.", "Hepatotoxicidad (incluida peliosis hepática y tumores), colesterol HDL reducido, supresión gonadal, virilización en mujeres y niños, cierre precoz de las epífisis; prohibida en el deporte."),
"Estimula a retenção de nitrogênio e síntese de proteínas.": ("Stimulates nitrogen retention and protein synthesis.", "Estimula la retención de nitrógeno y la síntesis de proteínas."),
"Lesão hepática (incluindo peliose e tumores), dislipidemia grave, hipertensão, virilização, dor articular, supressão gonadal e riscos de produtos falsificados ou veterinários; proibido no esporte.": ("Liver injury (including peliosis and tumors), severe dyslipidemia, hypertension, virilization, joint pain, gonadal suppression and risks from counterfeit or veterinary products; banned in sport.", "Lesión hepática (incluida peliosis y tumores), dislipidemia grave, hipertensión, virilización, dolor articular, supresión gonadal y riesgos de productos falsificados o veterinarios; prohibido en el deporte."),
"Aumenta a síntese proteica.": ("Increases protein synthesis.", "Aumenta la síntesis proteica."),
"Em animais de produção aumenta massa magra; em humanos não há benefício comprovado, só riscos.": ("In livestock it increases lean mass; in humans there is no proven benefit, only risks.", "En animales de producción aumenta la masa magra; en humanos no hay beneficio comprobado, solo riesgos."),
"Meia-vida não definida em humanos; dados vêm de animais.": ("Half-life not defined in humans; data come from animals.", "Vida media no definida en humanos; los datos provienen de animales."),
"Resultados com cortisona na artrite reumatoide renderam o Nobel de Medicina de 1950 a Kendall, Hench e Reichstein.": ("Results with cortisone in rheumatoid arthritis earned Kendall, Hench and Reichstein the 1950 Nobel Prize in Medicine.", "Los resultados con cortisona en la artritis reumatoide les valieron a Kendall, Hench y Reichstein el Nobel de Medicina de 1950."),
"Aprovada (FDA/Anvisa) como corticosteroide oral para doenças inflamatórias, alérgicas e imunológicas": ("Approved (FDA/Anvisa) as an oral corticosteroid for inflammatory, allergic and immunological diseases", "Aprobada (FDA/Anvisa) como corticosteroide oral para enfermedades inflamatorias, alérgicas e inmunológicas"),
"Ensaios e décadas de prática confirmam eficácia, com monitoramento de efeitos adversos.": ("Trials and decades of practice confirm efficacy, with monitoring for adverse effects.", "Ensayos y décadas de práctica confirman la eficacia, con monitoreo de efectos adversos."),
"Glicocorticoide sintético potente de ação longa que ativa o receptor de glicocorticoides, com efeito anti-inflamatório, imunossupressor e antiedematoso, quase sem atividade mineralocorticoide.": ("Potent, long-acting synthetic glucocorticoid that activates the glucocorticoid receptor, with anti-inflammatory, immunosuppressive and anti-edema effects and almost no mineralocorticoid activity.", "Glucocorticoide sintético potente de acción prolongada que activa el receptor de glucocorticoides, con efecto antiinflamatorio, inmunosupresor y antiedematoso, casi sin actividad mineralocorticoide."),
"Pessoas com infecções não tratadas, diabetes descompensado, úlcera ou psicose; atenção em uso prolongado e no esporte.": ("People with untreated infections, uncontrolled diabetes, ulcer or psychosis; caution with prolonged use and in sport.", "Personas con infecciones no tratadas, diabetes descompensada, úlcera o psicosis; atención en el uso prolongado y en el deporte."),
"Hipertensão, edema, hipocalemia, insuficiência cardíaca e cefaleia; requer monitoramento de pressão e eletrólitos.": ("Hypertension, edema, hypokalemia, heart failure and headache; requires monitoring of blood pressure and electrolytes.", "Hipertensión, edema, hipopotasemia, insuficiencia cardíaca y cefalea; requiere monitoreo de la presión arterial y los electrolitos."),
"Aumenta a reabsorção de sódio e água.": ("Increases sodium and water reabsorption.", "Aumenta la reabsorción de sodio y agua."),
"Estudos com antagonistas mostram que bloquear sua ação protege pacientes com insuficiência cardíaca.": ("Studies with antagonists show that blocking its action protects patients with heart failure.", "Estudios con antagonistas muestran que bloquear su acción protege a pacientes con insuficiencia cardíaca."),
"Meia-vida plasmática de cerca de 20 minutos.": ("Plasma half-life of about 20 minutes.", "Vida media plasmática de unos 20 minutos."),
"Reverte rapidamente a anafilaxia e é usada em paradas cardíacas.": ("Rapidly reverses anaphylaxis and is used in cardiac arrest.", "Revierte rápidamente la anafilaxia y se usa en paros cardíacos."),
}
